// Recovery-R4 authoritative closure types. These add no accepted-owner fields;
// they bind stored rows, current guards and delivery/recovery state.
export type R4ProjectionQuality = "ACCEPTED" | "REJECTED" | "HELD" | "REWORK" | "UNEXAMINED";
export type R4PayloadSchemaType = "OutQualityTaskResult" | "OutQualityDisposition" | "ExecQualityTaskResult" | "ExecQualityDisposition" | "RawEvidenceHandoff";
export type R4WriteEnvelope<T> = Readonly<{
  op: "INSERT" | "UPDATE";
  table: string;
  key: string;
  row: T & EnvironmentKey & Readonly<{ table: string; key: string; BodyJson: string; BodyDigest: Digest }>;
}>;
export type R4OwnerOriginal<TBody> = Readonly<EnvironmentKey & {
  Owner: "MES-EXEC" | "MES-OUTPUT";
  OwnerId: Id;
  OwnerRevision: Ver;
  OriginalBody: TBody;
  OriginalDigest: Digest;
}>;
export type R4OutcomeIdentity = Readonly<EnvironmentKey & {
  resultSetId: UUID; resultSetRevision: Ver; outcomeId: UUID;
  range: QapRange; quality: R4ProjectionQuality; bodyDigest: Digest;
}>;
export type R4FrozenPayload = Readonly<EnvironmentKey & {
  payloadId: UUID; payloadType: PayloadType; schemaType: R4PayloadSchemaType;
  payloadDigest: Digest; registrationRef: QapEvidence; frozenAt: Time;
}>;
export type R4FrozenDelivery = Readonly<EnvironmentKey & {
  deliveryId: UUID; canonicalKey: ShortText; sequence: Ver;
  sourceRef: QapEvidence; decisionRef: QapEvidence | null; payloadRef: QapEvidence;
  registrationRef: QapEvidence; payloadDigest: Digest;
  state: "PENDING" | "UNKNOWN" | "APPLIED" | "REJECTED";
  leaseEpoch: Ver; leaseVersion: Ver;
}>;
export type R4SourceCorrectionImpact = Readonly<{
  sourceRef: QapEvidence; previousSourceRef: QapEvidence; affectedRanges: ReadonlyArray<QapRange>;
  oldDecisionRef: QapEvidence; action: "REOPEN_SUCCESSOR_REQUIRED"; state: "RECORDED";
}>;
export type R4ResultInvalidation = Readonly<{
  resultSetRef: QapEvidence; reason: "SOURCE_OBSERVATION_CORRECTED";
  state: "INVALIDATED"; invalidatedAt: Time;
}>;
export type R4WriterEpochVersion = Readonly<{
  epoch: Ver; state: "PREPARED" | "ACTIVE" | "RETIRED";
  preparedAt?: Time; activatedAt: Time | null; retiredAt: Time | null;
}>;
export type WriterEpochTransitionCommand = { commandId: UUID; requestKey: ShortText; inputDigest: Digest; writerName: ShortText; action: "PREPARE" | "ACTIVATE" | "RETIRE"; expectedHeadEpoch: Ver; targetEpoch: Ver; authorityRef: QapEvidence; };
export type WriterEpochTransitionOutcome = { state: "COMMITTED"; commandId: UUID; requestKey: ShortText; inputDigest: Digest; result: WriterEpochResult; problem: null; terminalType: "WriterEpochResult"; terminalDigest: Digest; recordedAt: Time; };
export type R4FrontendActionBinding = Readonly<{
  actionId: ShortText; scenarioId: ShortText; apiCode: ShortText;
  requestPath: ShortText; responsePath: ShortText; executionContext: EnvironmentKey;
  expectedCurrentInputs: Readonly<Record<string, unknown>>;
  ownerLookups: ReadonlyArray<Readonly<{ path: ShortText; evidence: QapEvidence }>>;
  terminal: Readonly<{ state: "COMMITTED" | "REJECTED"; terminalType: ShortText; terminalDigest: Digest }>;
  recovery: Readonly<{ kind: "C01_TERMINAL_REPLAY"; commandId: UUID; requestKey: ShortText }>;
}>;

